-- Geographic reference data. Stable IDs intentionally match the frontend contract.
CREATE TABLE IF NOT EXISTS "${schemaName}".countries (
    country_id varchar(64) PRIMARY KEY, country_code varchar(2) NOT NULL UNIQUE,
    country_name varchar(100) NOT NULL, calling_code varchar(10), display_order integer NOT NULL,
    is_active boolean NOT NULL DEFAULT true, created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by varchar(64) NOT NULL, updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL, is_deleted boolean NOT NULL DEFAULT false, version_no integer NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS "${schemaName}".regions (
    region_id varchar(64) PRIMARY KEY, country_id varchar(64) NOT NULL REFERENCES "${schemaName}".countries(country_id),
    country_code varchar(2) NOT NULL, region_code varchar(10) NOT NULL, region_name varchar(100) NOT NULL,
    display_order integer NOT NULL, is_active boolean NOT NULL DEFAULT true,
    created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by varchar(64) NOT NULL,
    updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by varchar(64) NOT NULL,
    is_deleted boolean NOT NULL DEFAULT false, version_no integer NOT NULL DEFAULT 1,
    CONSTRAINT ux_regions_country_code UNIQUE (country_id, region_code)
);
CREATE TABLE IF NOT EXISTS "${schemaName}".cities (
    city_id varchar(128) PRIMARY KEY, country_id varchar(64) NOT NULL REFERENCES "${schemaName}".countries(country_id),
    region_id varchar(64) NOT NULL REFERENCES "${schemaName}".regions(region_id), country_code varchar(2) NOT NULL,
    region_code varchar(10) NOT NULL, city_name varchar(150) NOT NULL, display_order integer NOT NULL,
    is_active boolean NOT NULL DEFAULT true, created_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by varchar(64) NOT NULL, updated_at timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL, is_deleted boolean NOT NULL DEFAULT false, version_no integer NOT NULL DEFAULT 1,
    CONSTRAINT ux_cities_region_name UNIQUE (region_id, city_name)
);
CREATE INDEX IF NOT EXISTS ix_regions_country_code ON "${schemaName}".regions(country_code) WHERE is_active AND NOT is_deleted;
CREATE INDEX IF NOT EXISTS ix_cities_country_region ON "${schemaName}".cities(country_code, region_code) WHERE is_active AND NOT is_deleted;

